<?php
require_once __DIR__.'/../../includes/staff/feature-tools.php';require_permission('inspiration.manage');verify_csrf();$pdo=staff_db();feature_table($pdo,'inspiration_designs');$staff=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'){$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',fpost('title')),'-'));$pdo->prepare('INSERT INTO inspiration_designs(title,slug,style_name,room_type,description,cover_image,base_design_id,is_featured,is_published,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([fpost('title'),$slug,fpost('style_name')?:null,fpost('room_type')?:null,fpost('description')?:null,fpost('cover_image')?:null,fint('base_design_id'),isset($_POST['is_featured'])?1:0,isset($_POST['is_published'])?1:0,$staff['id']]);flash('success','Inspiration design added.');staff_redirect('staff/admin/inspiration.php');}
$designs=db_rows($pdo,'SELECT id,design_code,title FROM designs ORDER BY updated_at DESC');$rows=db_rows($pdo,'SELECT * FROM inspiration_designs ORDER BY is_featured DESC,sort_order,created_at DESC');$pageTitle='Inspiration Gallery';require __DIR__.'/../../includes/staff/header.php';module_head('Public Website','Cabinet Inspiration Gallery','Publish styles customers can browse and use as a starting point in the configurator.');?>
<section class="staff-panel"><form method="post" class="mini-form"><?=csrf_field()?><label>Title<input name="title" required></label><label>Style<input name="style_name" placeholder="Japandi"></label><label>Room<input name="room_type" placeholder="Kitchen"></label><label>Base design<select name="base_design_id"><option value="">None</option><?php foreach($designs as $d):?><option value="<?=$d['id']?>"><?=h($d['design_code'].' · '.$d['title'])?></option><?php endforeach?></select></label><label>Cover image path<input name="cover_image"></label><label>Description<input name="description"></label><label><input type="checkbox" name="is_featured"> Featured</label><label><input type="checkbox" name="is_published"> Published</label><button class="btn primary">Add inspiration</button></form></section><section class="staff-panel table-panel"><table><thead><tr><th>Design</th><th>Style</th><th>Room</th><th>Published</th><th>Featured</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=h($r['title'])?></b></td><td><?=h($r['style_name']?:'—')?></td><td><?=h($r['room_type']?:'—')?></td><td><?=$r['is_published']?'Yes':'No'?></td><td><?=$r['is_featured']?'Yes':'No'?></td></tr><?php endforeach?></tbody></table></section><?php module_end();require __DIR__.'/../../includes/staff/footer.php';?>